LIST_TBSPACES = "select TBSPACE from syscat.tablespaces WITH UR"
LIST_SCHEMAS = "select SCHEMANAME from syscat.schemata WITH UR"
TABLE_DETAILS = "SELECT TBSPACE, TABSCHEMA, TABNAME FROM SYSCAT.TABLES WHERE TABLEORG='C' AND TBSPACE in ({TBSPACES}) AND TABSCHEMA in ({TABSCHEMAS}) AND TABNAME in ({TABNAMES}) WITH UR"
LIST_TABLES_IN_TSPACE = "select TABNAME, TABSCHEMA from syscat.tables where TBSPACE='{TABLESPACE}' AND TABLEORG='C' WITH UR "
LIST_TABLES_IN_SCHEMA = "select TABNAME, TBSPACE from syscat.tables where TABSCHEMA ='{SCHEMANAME}' AND TABLEORG='C' WITH UR"
LIST_TBSPACE_BY_TABNAME = "select TBSPACE from syscat.tables where TABNAME = '{TABNAME}' AND TABSCHEMA ='{SCHEMANAME}' WITH UR"
TAB_SIZE = "SELECT SUM(DATA_OBJECT_P_SIZE), SUM(INDEX_OBJECT_P_SIZE), SUM(LONG_OBJECT_P_SIZE), SUM(LOB_OBJECT_P_SIZE), SUM(XML_OBJECT_P_SIZE) FROM SYSIBMADM.ADMINTABINFO WHERE TABSCHEMA='{TABSCHEMA}' AND TABNAME='{TABNAME}'  GROUP BY TABSCHEMA, TABNAME WITH UR"
ADM_MOVE_TABLE_FIND_PHASE = "SELECT VALUE FROM SYSTOOLS.ADMIN_MOVE_TABLE WHERE KEY='STATUS' AND TABNAME='{TABLENAME}' WITH UR"
ADM_MOVE_TABLE_STRUCK_PHASE = "SELECT TABNAME FROM SYSTOOLS.ADMIN_MOVE_TABLE WHERE KEY='TARGET' AND VALUE='{TABLENAME}' WITH UR"
ROW_COUNT = "select count(*) from '{TABLENAME}'  WITH UR;"
ADM_MOVE_TABLE_FIND_TARGET_TABLE = "SELECT VALUE FROM SYSTOOLS.ADMIN_MOVE_TABLE WHERE KEY='TARGET' AND TABNAME='{TABLENAME}' WITH UR"
ADM_MOVE_TABLE_FIND_SOURCE_TABLE = "SELECT VALUE FROM SYSTOOLS.ADMIN_MOVE_TABLE WHERE KEY='TARGET' AND TABNAME='{TABLENAME}' WITH UR"
GET_THE_ROW_COUNT = "SELECT sum(rows_inserted) FROM TABLE(MON_GET_TABLE('','',-2)) where tabschema='{SCHEMANAME}' and tabname='{TABLENAME}' WITH UR"
GET_THE_ROW_COUNT_FROM_TABLE_AFTER_COPY = "SELECT COUNT(*) FROM {SCHEMANAME}.{TABLENAME} WITH UR"
GET_STORAGE_PATH_DEFINED_IN_INSTANCE = "SELECT STORAGE_GROUP_NAME,DB_STORAGE_PATH FROM TABLE(ADMIN_GET_STORAGE_PATHS('',-1)) AS T WITH UR"
GET_OBJECTSPACE_USING_SGNAME = "SELECT TBSPACE from syscat.tablespaces where SGNAME='{SGNAME}' WITH UR"
GET_USER_CREATED_INDEX = "SELECT t.TBSPACE, i.OWNERTYPE FROM SYSCAT.INDEXES i JOIN SYSCAT.TABLESPACES t ON i.TBSPACEID = t.TBSPACEID WHERE i.TABSCHEMA = '{SCHEMANAME}' AND i.TABNAME = '{TABLENAME}';"
RUNSTATS_FOR_TABLE = "CALL SYSPROC.ADMIN_CMD ('RUNSTATS ON TABLE {SCHEMANAME}.{TABLENAME} WITH DISTRIBUTION AND DETAILED INDEXES ALL')"
LIST_PARENT_TABLES = "SELECT REFTABNAME, REFTABSCHEMA FROM SYSCAT.REFERENCES WHERE TABNAME='{TABNAME}' AND TABSCHEMA='{SCHEMANAME}';"
CREATE_TABLESPACE = "CREATE TABLESPACE {TABLESPACE} USING STOGROUP {STORAGE_GROUP}"
SYSTOOLS_ADMIN_MOVE_TABLE = "SELECT TABSCHEMA, TABNAME  FROM SYSCAT.TABLES WHERE TABSCHEMA = 'SYSTOOLS' AND TABNAME = 'ADMIN_MOVE_TABLE';"
ADM_MOVE_STATUS = "SELECT CAST(VALUE AS VARCHAR(100)) FROM SYSTOOLS.ADMIN_MOVE_TABLE WHERE KEY='STATUS' AND TABSCHEMA='{SCHEMA}' AND TABNAME='{TABLENAME}';"
ADM_MOVE_ACTIVE_UTILITY = "SELECT UTILITY_OPERATION_TYPE FROM TABLE(SYSPROC.MON_GET_UTILITY(-2)) WHERE OBJECT_TYPE='TABLE' AND OBJECT_SCHEMA='{SCHEMA}' AND OBJECT_NAME='{TABLENAME}' AND UTILITY_TYPE='MOVETABLE';"
